            if (a.Count != b.Count) return false;
            for (int i = 0; i < a.Count; i++) if (!(a[i] == b[i])) return false;
            return true;
        }

        private static bool _quod_eq_2(int a, int b)
        {
            return a == b;
        }

        private static bool _quod_eq_3(IReadOnlyList<Catalog.Line> a, IReadOnlyList<Catalog.Line> b)
        {
            if (a.Count != b.Count) return false;
            for (int i = 0; i < a.Count; i++) if (!a[i].Equals(b[i])) return false;
            return true;
        }

        private static bool _quod_eq_4(Catalog.Line a, Catalog.Line b)
        {
            return a.Equals(b);
        }
    }
